    public static class JuliuszSłowacki
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Miłość – to światło, to niebo, to życie!", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Pawiem narodów byłaś i papugą A teraz jesteś służebnicą cudzą.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Sęp ci wyjada nie serce – lecz mózgi.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Jam się w miłość nieszczęsną całym sercem wsączył…", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Mam sto rąk, sto sztyletów… gdy chcę, sto ran zadam.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Nie mam wiary, Gdzie ludzie oddychają, ja oddech utracam.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Jeżeli gryzę co – to sercem gryzę.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Biada, kto daje ojczyźnie pół duszy, A drugie tu pół dla szczęścia zachowa.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Strofa być winna taktem, nie wędzidłem.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Ale ty próżno będziesz krajobrazy tworzyć, Osrebrzać je księżycem – i promienić świtem. Nie wiesz, że trzeba niebo zwalić, i położyć Pod oknami, i nazwać jeziora błękitem.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Bo ci w westchnieniach oddawałem lata, A ty płaciłaś je pocałunkami.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Bo kiedy już przeszłość ten step mi zakryje, Gdy żyć będzie ciężko, to sam się zabiję, Bo dziką mam duszę. Więc sztylet mieć muszę, Twój sztylet mieć muszę przy sobie.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Co nam zdrady! – Jest u nas kolumna w Warszawie.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Czas wszystko odkryje, czas złym jest powiernikiem.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Dosyć jest ludzi strzegących mizernych swoich pozycji i dumy własnej, i czci światowej… i fałszów… ale muszą być i tacy, co zapomną o sobie – a wtenczas będą silni i niepokonani.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Duchowi memu dała w pysk i poszła.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Gdybym był duchem wersalskiej natury, A taką Ciebie między tłumem zoczył, Zleciałbym na cię jak kaskada z góry, Porwał — i rzucił w przepaść — i sam skoczył.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Kobieta się rodzi gwiazdom podległa i kwiatom.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Lauro — ja nieszczęśliwy, idąc w kraj daleki, Myślę, że wrócę kiedyś spocząć na twem łonie... Próżne marzenia — żegnam, żegnam cię na wieki.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Lecz zaklinam – niech żywi nie tracą nadziei I przed narodem niosą oświaty kaganiec; A kiedy trzeba, na śmierć idą po kolei, Jak kamienie przez Boga rzucane na szaniec!", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Ledwo słońce na wschodzie odsłoni swe lica, Ledwo spojrzy po cichej, samotnej dolinie, Mgła się mieni w łzy róży i na kwiaty spłynie, Chyli się pod perłami róża krasnolica.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Może w tym położeniu śmierć mnie zastanie.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Nie czas żałować róż, gdy płoną lasy.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Niechaj mię Zośka o wiersze nie prosi, Bo kiedy Zośka do ojczyzny wróci, To każdy kwiatek powie wiersze Zosi, Każda jej gwiazdka piosenkę zanuci.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "O Boże! Daj mi sławę choć po śmierci, a za to niech będę najnieszczęśliwszym, pogardzanym i nie poznanym w moim życiu.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "O! gdybym ja wiódł Panią do kaskady!", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Po długich latach, gdy wiek sił ukróci, Gdy będziesz myślą w złotej przeszłości się stawił, Wspomnij na przyjaciela, który cie zostawił, Jak przeszłość zniknął, jak przeszłość nie wróci.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Pośród niesnasków Pan Bóg uderza W ogromny dzwon. Dla słowiańskiego oto papieża Otwarty tron.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Powiem i w rymy to włożę królewskie: Że choć widziałem w oczach cztery zmiany, Prawdziwie Lolka ma oczy niebieskie.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Przeklęta! Ty wydarłaś ostatnie godziny Szczęścia mego na ziemi, ty żądłem gadziny Wygnałaś na samotność! Bądź wiecznie przeklęta! — Każdy mój jęk — zna ciebie, każda łza — pamięta!", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Rozłączeni — lecz jedno o drugim pamięta; Pomiędzy nami lata biały gołąb smutku I nosi ciągłe wieści. — Wiem, kiedy w ogródku, Wiem, kiedy płaczesz w cichej komnacie zamknięta.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Słowa dziecka to staremu kwiaty.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Smutno mi, Boże! Dla mnie na zachodzie Rozlałeś tęczę blasków promienistą; Przede mną gasisz w lazurowej wodzie Gwiazdę ognistą… Choć mi tak niebo Ty złocisz i morze, Smutno mi, Boże!", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Szli krzycząc: „Polska! Polska” Wtem Bóg z mojżeszowego pokazał się krzaka, Spojrzał na te krzyczące i zapytał: „Jaka?”", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Ten, kto się śmieje, zawsze płaczących zwycięża.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Ten świat jest to dywanik na wywrót widziany, gdzie różne nitki wyłażą i giną znów niby bez celu i bez potrzeby… z tamtej strony są kwiaty i rysunek.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Zaledwo w serce moje spojrzała dziewica, Ledwom zaczął żyć dla niej i dla niej jedynie, Szczęście w łzy się zmieniło, mgła omamień ginie, Błyszczy gorzkiemi łzami zalana źrenica.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Żem był jak pielgrzym, co się w drodze trudzi Przy blaskach gromu. Że nie wiem, gdzie się w mogiłę położę, Smutno mi, Boże!", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Żyłem z wami, cierpiałem i płakałem z wami, Nigdy mi, kto szlachetny, nie był obojętny, Dziś was rzucam i dalej idę w cień — z duchami A jak gdyby tu szczęście było — idę smętny.", Author = "Juliusz Słowacki" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Juliusz_Słowacki", Text = "Medale rosły w olbrzymie posągi, Kurwy odeskie zmieniały [w] grafinie. Nie tak to widzisz, Adamitku, nynie. Nie tak to nynie — jak to było ongi.", Author = "Juliusz Słowacki" },
        };
    }
}